B.aFF=new A.f1("sql_server_sync_snapshots","TRACK_5","Tax, Export & Cloud Sync","Cloud Sync, App Health & Safety Snapshots",B.aL1,"Bidirectional sync between Android Room DB, Flutter Web, and the SQL Server CoreApi backend with instant rollback snapshots.",B.c6B,null,"/cloud-sync")
